// Payload do Workestrator: o corpo do POST fica em `body` no nó de webhook (typeVersion 2.1).
// Ler `$json` direto (sem `.body`) devolve headers/params/query e todo campo de negócio vira undefined.
const p = $input.first().json.body;

// ÚNICO lugar do sistema que conhece o esquema do chamado. O Workestrator manda `item.data` como
// passthrough de propósito (design D15) — o backend não interpreta esses nomes.
const F = {
  processo: 'NUM_PROCESS',
  solicitante: 'SOLICITANTE_NOME',
  necessidade: 'SOLICITANTE_NECESSIDADE',
  criticidade: 'SOLICITANTE_CRITICIDADE_SOLICITANTE',
  reclassificada: 'SOLICITANTE_CRITICIDADE_RECLASSIFICADA',
  executor: 'EXECUTOR_RESPONSAVEL',
};

// `SOLICITANTE_NECESSIDADE` é texto livre digitado pelo solicitante — um `<` ou `&` solto quebraria o
// HTML do card no Teams (mensagem truncada ou tags aparecendo cruas).
const esc = (v) => String(v == null || v === '' ? '—' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const TD = 'border:1px solid #ddd;padding:6px 10px';
const linha = (rotulo, valor) =>
  `<tr><td style="${TD};background:#f4f4f4;white-space:nowrap"><b>${rotulo}</b></td>` +
  `<td style="${TD}">${esc(valor)}</td></tr>`;

const itens = Array.isArray(p.items) ? p.items : [];

// Checkpoint sem itens (agente respondeu em prosa, não em lista JSON) — manda UMA mensagem de resumo.
// Sem esse ramo, um checkpoint booleano não geraria mensagem nenhuma e o aviso sumiria em silêncio.
if (itens.length === 0) {
  const html = [
    `<b>${esc(p.title)}</b>`,
    esc(p.summary),
    `<a href="${p.decisionUrl}">Abrir no Workestrator</a>`,
  ].join('<br>');
  return [{ json: { html, approvalId: p.approvalId ?? null, itemId: null } }];
}

// Um item de saída por chamado ⇒ o nó do Teams roda uma vez por chamado, cada mensagem com o seu
// próprio link de decisão. É o "uma aprovação por chamado" pedido.
return itens.map((item, i) => {
  const d = item.data || {};
  const html = [
    `<b>Chamado ${esc(d[F.processo] || item.ref)}</b> — ${i + 1} de ${itens.length}`,
    `<table style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;margin-top:8px">`,
    linha('Solicitante', d[F.solicitante]),
    linha('Necessidade', d[F.necessidade]),
    linha('Criticidade informada', d[F.criticidade]),
    linha('Reclassificação proposta', d[F.reclassificada]),
    linha('Executor indicado', d[F.executor]),
    `</table>`,
    `<br><a href="${item.decisionUrl}">Aprovar ou reprovar este chamado</a>`,
  ].join('');
  return { json: { html, approvalId: p.approvalId ?? null, itemId: item.id, ref: item.ref ?? null } };
});
